package wgmodern;
import net.minecraftforge.common.ForgeConfigSpec;
public class WGConfig {
    public static final ForgeConfigSpec CLIENT;
    public static final ForgeConfigSpec.IntValue CLOAK_ANIMATION;
    public static final ForgeConfigSpec.BooleanValue LIMIT_BOOK_SEARCH;
    public static final ForgeConfigSpec.DoubleValue RADIAL_SPEED;
    public static final ForgeConfigSpec SERVER;
    public static final ForgeConfigSpec.BooleanValue CLUSTERS,TRANSMUTATIONS,BOOTS_REPAIR,POUCH_ACTIVE,LUCK_MODIFIERS,PRIMORDIAL_POTIONS;
    public static final ForgeConfigSpec.ConfigValue<java.util.List<? extends String>> HILLTOP_GROUND,RING_GROUND,TRIPLING_CLUSTERS;
    public static final ForgeConfigSpec.IntValue SMELTERY_CLUSTER_AMOUNT;
    static{var b=new ForgeConfigSpec.Builder();CLOAK_ANIMATION=b.comment("Legacy cloak animation: 0 disabled, 1 sway, 2 cloth stretching.").comment("披风动画：0 关闭，1 摆动，2 布料拉伸", "设置说明 / Setting: Cloak animation: 0 off, 1 sway, 2 cloth stretching", "初始值 / Default: " + String.valueOf(2) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(2), "客户端重载配置后生效 / Applies after client config reload.").defineInRange("cloakAnimationMode",2,0,2);LIMIT_BOOK_SEARCH=b.comment("知识书搜索仅限当前研究分类", "设置说明 / Setting: Limit knowledge-book searches to the current research category", "初始值 / Default: " + String.valueOf(false) + "; 可选 / Allowed: true, false", "客户端重载配置后生效 / Applies after client config reload.").define("limitBookSearchToCategory",false);RADIAL_SPEED=b.comment("环形选择菜单展开速度", "设置说明 / Setting: Radial selection menu expansion speed", "初始值 / Default: " + String.valueOf(.15) + "; 范围 / Range: " + String.valueOf(.15) + ".." + String.valueOf(1), "客户端重载配置后生效 / Applies after client config reload.").defineInRange("selectionRadialSpeed",.15,.15,1);CLIENT=b.build();}
    static{var b=new ForgeConfigSpec.Builder();
    var tripling=new java.util.ArrayList<>(Metallurgy.METALS);tripling.add("uranium");
    TRIPLING_CLUSTERS=b.comment("高炉三倍冶炼的额外矿簇材料名（forge:clusters/ 后缀）；默认旧版金属列表，空列表禁用额外矿簇。内置配方仍优先；重启世界。", "Extra cluster materials tripled by the blast furnace (forge:clusters/ suffixes); defaults to the legacy metal list. Empty disables extra clusters; explicit datapack recipes still take priority. Restart the world.").defineListAllowEmpty("triplingClusterMaterials",tripling,v->v instanceof String s&&net.minecraft.resources.ResourceLocation.tryParse("forge:clusters/"+s)!=null);
    CLUSTERS=b.comment("Enable the original optional-metal clusters. Restart after changing this option.").comment("启用原有可选金属矿簇", "设置说明 / Setting: Enable original optional-metal clusters", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("enableClusters",true);TRANSMUTATIONS=b.comment("Enable original nugget transmutations. Disable to avoid legacy transmutation loops.").comment("启用原有金属粒嬗变；关闭可避免旧版嬗变循环", "设置说明 / Setting: Enable original nugget transmutations; disable to avoid legacy transmutation loops", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("enableTransmutations",true);BOOTS_REPAIR=b.comment("允许用皮革修复旅行者之靴", "设置说明 / Setting: Allow leather repairs of Traveller Boots", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("allowTravellerBootsLeatherRepair",true);POUCH_ACTIVE=b.comment("允许激活已装备的法杖核心袋", "设置说明 / Setting: Allow activation of an equipped focus pouch", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("allowEquippedFocusPouchActivation",true);LUCK_MODIFIERS=b.comment("幸运戒指影响时运和抢夺", "设置说明 / Setting: Luck Ring affects Fortune and Looting", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("allowLuckRingFortuneAndLooting",true);PRIMORDIAL_POTIONS=b.comment("元始护甲修正扭曲药水效果", "设置说明 / Setting: Primordial armor modifies warp potion effects", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("allowPrimordialArmorWarpEffectModification",true);SMELTERY_CLUSTER_AMOUNT=b.comment("Original units: 144 equals one ingot; converted to the installed smeltery's ingot unit. Zero disables melting recipes.").comment("矿簇熔炼流体量；旧制 144 为一锭，自动换算现代单位；0 禁用", "设置说明 / Setting: Cluster smeltery output; legacy 144 means one ingot, converted to modern units; 0 disables", "初始值 / Default: " + String.valueOf(432) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(Integer.MAX_VALUE), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("smelteryResultForClusters",432,0,Integer.MAX_VALUE);var grounds=java.util.List.of("minecraft:stone","minecraft:sand","minecraft:packed_ice","minecraft:grass_block","minecraft:gravel","minecraft:dirt");HILLTOP_GROUND=b.comment("山顶石允许生成的地面方块注册 ID；空列表禁用", "设置说明 / Setting: Allowed ground block IDs for hilltop stones; empty disables", "初始值 / Default: " + String.valueOf(grounds) + "; 列表允许为空 / An empty list is allowed", "修改后重启世界或服务器 / Restart the world/server after editing.").defineListAllowEmpty("validHilltopStoneGrounds",grounds,x->x instanceof String s&&net.minecraft.resources.ResourceLocation.tryParse(s)!=null);RING_GROUND=b.comment("邪术石环允许生成的地面方块注册 ID；空列表禁用", "设置说明 / Setting: Allowed ground block IDs for Eldritch rings; empty disables", "初始值 / Default: " + String.valueOf(grounds) + "; 列表允许为空 / An empty list is allowed", "修改后重启世界或服务器 / Restart the world/server after editing.").defineListAllowEmpty("validEldritchRingGrounds",grounds,x->x instanceof String s&&net.minecraft.resources.ResourceLocation.tryParse(s)!=null);SERVER=b.build();}
    public static boolean allowedGround(net.minecraft.world.level.block.Block block,boolean ring){var key=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getKey(block);return key!=null&&(ring?RING_GROUND:HILLTOP_GROUND).get().contains(key.toString());}
}
